export type RetrievalSubTimingMetrics = { kbTotalMs: number; kbScopeLoadMs: number; kbHydeInterpretationMs: number; kbSearchPlanMs: number; kbShortlistPlanningMs: number; kbQueryExecutionMs: number; kbMergeShortlistGateMs: number; kbPostFiltersMs: number; kbRerankMs: number;
/**
 * Cost of the post-rerank sufficiency check. Local and cheap by design —
 * if this is ever material, the check is doing too much.
 */
kbSufficiencyMs: number;
/**
 * The whole corrective second pass: replanning, both branches again, and
 * the second rerank. Zero when no retry ran.
 */
kbCorrectiveRetryMs: number;
/**
 * 0 or 1. The loop is capped at exactly one replanned retry per turn.
 */
kbCorrectiveRetries: number;
/**
 * The final sufficiency verdict, or `None` when KB retrieval never ran.
 * Absent is not the same as insufficient.
 */
kbSufficient: boolean | null;
/**
 * True when a short follow-up reused the previous turn's topic and the
 * planner LLM call was skipped.
 */
kbPlannerSkipped: boolean; kbBuildSourcesMs: number; kbPersistReferencesMs: number;
/**
 * Wall-clock of external query preparation: the utility model's
 * interpretation and the web-query rewrite, which run concurrently.
 */
externalHydeInterpretationMs: number; wikiSearchMs: number;
/**
 * The web search itself. Query rewriting is counted above, not here.
 */
webSearchMs: number; totalMs: number }
/**
 * Retrieval trace for one turn.
 *
 * `searched_documents` is the size of the document set the hard space-scope
 * filter actually allowed, not the size of the corpus — a scoped conversation
 * must not claim to have read the whole vault.
 *
 * Shared by streaming events, persisted message metadata, and generated bindings.
 */
export type RetrievalTraceDto = { searchedDocuments: number; passages: number; files: number;
/**
 * Web pages carried into the answer, counted apart from `files`.
 *
 * `files` means documents in the user's vault and nothing else. Web
 * results used to be counted there too, so a web-only answer in a space
 * holding no documents still reported "10 passages from 10 files" — which
 * reads as though it had searched the vault, and is the sort of claim that
 * makes a correctly scoped answer look like a leak.
 */
webPages: number;
/**
 * "vault" | "linked"
 */
scope: string;
/**
 * Why the knowledge base could not be searched, when it could not be.
 */
unavailableReason?: string | null;
/**
 * The post-rerank sufficiency verdict, after any corrective pass.
 *
 * Additive and absent by default: traces persisted before the sufficiency
 * check existed carry no verdict, and absent is not the same as
 * insufficient. Every consumer must tolerate `null` rather than read a
 * missing verdict as a failure.
 */
kbSufficient?: boolean | null;
/**
 * How many replanned retrieval passes ran. Capped at one per turn, so this
 * is 0 or 1; absent when the check did not run at all.
 */
kbCorrectiveRetries?: number | null;
/**
 * True when a short follow-up reused the previous turn's topic and the
 * planner LLM call was skipped.
 */
kbPlannerSkipped?: boolean | null;
/**
 * Why the verdict went the way it did — stable codes (`low_top_score`,
 * `low_term_coverage`, …), not prose, so the UI and tests can match on
 * them.
 */
sufficiencyReasons?: string[];
/**
 * How many documents this turn was pinned to, when it was pinned at all.
 *
 * The count after the intersection with the space scope, so `Some(0)`
 * means the request named documents this chat cannot reach and the turn
 * searched nothing — which is what fails closed looks like from outside.
 */
focusedDocuments?: number | null }
/**
 * Retrieval pipeline tuning settings.
 */
export type RetrievalTuningSettingsDto = {
/**
 * Min and max KB candidate limits derived from tool output max_results
 */
kbSearchMinLimit: number; kbSearchMaxLimit: number;
/**
 * Min and max limits for document shortlist candidate collection
 */
docShortlistCandidateMin: number; docShortlistCandidateMax: number;
/**
 * Min and max document count kept in document shortlist
 */
docShortlistDocMin: number; docShortlistDocMax: number;
/**
 * Minimum shortlist confidence required before gating
 */
shortlistGateMinCandidates: number; shortlistGateMinDocs: number;
/**
 * External source retrieval limits and snippet shaping
 */
wikiSearchMaxResults: number; wikiSnippetMaxChars: number; wikiContextLimit: number; webSearchMaxResults: number; webSnippetMaxChars: number;
/**
 * How many of the top web results are opened and read in full for the
 * prompt. Search engines return a headline and roughly one sentence; a
 * question about what a page actually says cannot be answered from that.
 * 0 disables page reading and falls back to snippets alone.
 */
webFetchPageCount: number;
/**
 * Ceiling on any one fetched page's text in the prompt. The room a page
 * actually gets is its share of the turn's page budget, which is derived
 * from the model's context window; this only caps that share.
 */
webPageMaxChars: number;
/**
 * Seconds any one page fetch may take before it is abandoned and the
 * result falls back to its snippet.
 */
webPageFetchTimeoutSecs: number; deepResearchDepth: number; deepResearchBranchQueries: number;
/**
 * External search query rewriting constraints
 */
externalSearchMaxWikiTerms: number; externalSearchMaxWebTerms: number; externalSearchQueryMaxChars: number;
/**
 * Cross-encoder reranking constraints
 */
rerankMaxCandidates: number; rerankQueryMaxChars: number;
/**
 * Corrective retrieval: when the post-rerank sufficiency check fails, the
 * planner is asked once for different queries and the passes are fused.
 * The score floor is only read when a cross-encoder actually ran — RRF
 * ranks are not probabilities and must never be thresholded.
 */
sufficiencyMinTopScore: number; sufficiencyMinTermCoverage: number; sufficiencyRetryEnabled: boolean;
/**
 * Lexical overlap precision control
 */
overlapMinHitsForMultiTerm: number;
/**
 * Document support filter tuning
 */
docSupportMultiHitRatioFactor: number; docSupportSingleHitRatioFactor: number; docSupportMultiHitRatioMin: number; docSupportMultiHitRatioMax: number; docSupportSingleHitRatioMin: number; docSupportSingleHitRatioMax: number }
